def summary(before, after):
    def dup(plan):
        events = plan["events"]
        return 1 - len({normalise(e["action"]) for e in events}) / len(events) if events else 0.0
    return dict(duplicate_rate_before=round(dup(before), 3), duplicate_rate_after=round(dup(after), 3))
